/** Integer feasibility and exhaustive allocation; no producer solver/answer import. */
import assert from 'node:assert/strict';import type{GeneratedBody}from'../../src/core/generators/definition';import review from'./legacy-2017-pm6-review.json';import{readPm6Display}from'./legacy-2017-pm6-document-reader';
const min=(tenths:number,months:number)=>{for(let n=0;n<100;n++)if(10*n*months>=tenths)return n;throw Error('BOUND');};
function solveCalendar(work:number[][],pair:number[]){
 const duration=[[3,3,pair[0],2,3],[3,3,pair[1],2,3]],needs=work.map((ws,s)=>ws.map((w,p)=>min(w,duration[s][p]))),A=Array.from({length:30},(_,i)=>i).find(n=>needs.every(ws=>5*n>=4*ws[0]))!;
 const schedule:number[][]=[[],[]];for(let s=0;s<2;s++){let month=s?6:0;for(let p=0;p<5;p++)for(let j=0;j<duration[s][p];j++)schedule[s][month++]=p;}
 const rows=[];for(let m=0;m<Math.max(...schedule.map(s=>s.length));m++){const p=[schedule[0][m],schedule[1][m]],need=p.map((q,s)=>q===undefined?0:needs[s][q]);let best=[0,0];for(let a=0;a<=A;a++)for(let b=0;b<=A-a;b++){if([a,b].some((n,s)=>n>need[s]||(p[s]===2||p[s]===undefined)&&n!==0))continue;if(a+b>best[0]+best[1]||a+b===best[0]+best[1]&&a>best[0])best=[a,b];}rows.push({month:m,unused:A-best[0]-best[1],A:best,B:need.map((x,s)=>x-best[s])});}return{A,rows,gaps:rows.filter(r=>r.unused).map(r=>r.month)};
}
export function inspectPm6(body:GeneratedBody,values:number[]){
 const display=readPm6Display(body),work=[0,2].map(i=>Array.from({length:5},(_,j)=>{const text=display.table1.get('table1:'+i+':'+j)!;assert.match(text,/^\d+\.\d$/);return Number(text.replace('.',''));})),base=solveCalendar(work,[4,4]),A=base.A;
 const b=min(work[0][0],3)-A,c=base.gaps.map(m=>'2017-'+m);assert.equal(c.length,1);const month=(base.gaps[0]+3)%12+1;
 const total=(index:number)=>display.months.filter(m=>m.table==='table3'&&m.company==='B社'&&m.index===index).reduce((n,m)=>{assert(m.value!==null);return n+m.value!;},0),before=[11,12,13].map(total);
 const moved=[];for(let e=1;e<=6;e++)for(let f=1;f<=6;f++){const after=[before[0]+e,before[1]-e-f,before[2]+f];moved.push({e,f,valid:after.every(n=>n===after[0])&&e<=display.months.find(m=>m.table==='table3'&&m.stage==='一期開発'&&m.company==='B社'&&m.index===12)!.value!&&f<=display.months.find(m=>m.table==='table3'&&m.stage==='二期開発'&&m.company==='B社'&&m.index===12)!.value!,after});}const sol=moved.filter(x=>x.valid);assert.equal(sol.length,1);assert.equal(before.reduce((a,b)=>a+b,0),sol[0].after.reduce((a,b)=>a+b,0));
 const truth=[display.banks.ab.map(n=>Number(n)===A),display.banks.ab.map(n=>Number(n)===b),display.banks.c.map(n=>n===month+'月'),display.banks.d.map(text=>{const pair=[...text.matchAll(/(?:一期|二期)開発を(\d)に/g)].map(m=>Number(m[1]));assert.equal(pair.length,2);return solveCalendar(work,pair).gaps.length===0;}),display.banks.ef.map(n=>Number(n)===sol[0].e),display.banks.ef.map(n=>Number(n)===sol[0].f)];assert(truth.every(t=>t.filter(Boolean).length===1));
 assert.deepEqual(body.answerParts?.map(p=>({id:p.id,label:p.label})),review.facts.answerParts.map(p=>({id:'part-'+p.id,label:p.id})));assert.deepEqual(body.answerParts?.map(p=>p.choiceIds.length),[6,6,4,4,6,6]);assert.deepEqual(body.answerParts![0].choiceIds,body.answerParts![1].choiceIds);assert.deepEqual(body.answerParts![4].choiceIds,body.answerParts![5].choiceIds);
 const semantic=[A,b,'2018-'+String(month).padStart(2,'0'),[...display.banks.d[truth[3].indexOf(true)].matchAll(/(?:一期|二期)開発を(\d)に/g)].map(m=>Number(m[1])),sol[0].e,sol[0].f],expected=review.numericExpectations.find(c=>c.values.join(',')===values.join(','))!;assert.deepEqual(semantic,expected.answerMeaning);
 truth.forEach((ts,i)=>{const part=body.answerParts![i],answer=body.partAnswers![i];assert(answer.kind==='choice');assert.equal(answer.partId,part.id);assert.equal(answer.choiceId,part.choiceIds[ts.indexOf(true)]);});
 assert.deepEqual(body.choices.map(bs=>{assert.equal(bs.length,1);assert(bs[0].type==='paragraph');return bs[0].text;}),Object.values(display.banks).flat());
 assert.equal(display.months.filter(m=>m.table==='table2'&&m.state==='hidden').length,44);assert.equal(display.months.filter(m=>m.table==='table3'&&m.state==='hidden').length,37);
 for(const t of review.facts.tables.slice(1))for(const [stage,cs]of Object.entries(t.staffing!))for(const [company,ms]of Object.entries(cs))ms.forEach((x,i)=>{const got=display.months.find(m=>m.table===t.id&&m.stage===stage&&m.company===company&&m.index===i)!;assert.equal(got.state,x.state);if(x.state!=='shown')assert.equal(got.value,null);});
 return{truth,comparisons:truth.reduce((n,x)=>n+x.length,0),eFTrials:moved.length,meaning:semantic,display};
}
